from sys import stdin, stdout

def can_direct_graph(n, m, edges):
    # Check if the graph is a tree
    if m != n - 1:
        return False

    # Build the adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find a leaf node
    for i in range(1, n + 1):
        if len(adj[i]) == 1:
            leaf = i
            break

    # Direct all edges towards the leaf node
    direction = ['0'] * m
    visited = set()
    stack = [(leaf, None)]
    while stack:
        node, parent = stack.pop()
        visited.add(node)
        for neighbor in adj[node]:
            if neighbor == parent:
                continue
            if neighbor not in visited:
                stack.append((neighbor, node))
                direction[edges.index((node, neighbor))] = '1'

    return True, ''.join(direction)

def main():
    n, m = map(int, stdin.readline().split())
    edges = [tuple(map(int, stdin.readline().split())) for _ in range(m)]

    result, direction = can_direct_graph(n, m, edges)

    if not result:
        stdout.write("NO\n")
    else:
        stdout.write("YES\n")
        stdout.write(direction + "\n")

if __name__ == "__main__":
    main()

